sources.wm_rank_oct.hpp:
#include <algorithm>
#include <array>
#include <bit>
#include <cassert>
#include <cstdint>
#include <immintrin.h>
#include <vector>

template <class T>
class WMOct {
	struct alignas(64) Block {
		std::array<std::uint32_t, 8> masks{}, prefix{};
	};
	int n, levels;
	std::vector<T> values;
	std::vector<std::vector<Block>> bits;
	std::vector<std::array<int, 8>> starts;
	bool avx2 = __builtin_cpu_supports("avx2") && __builtin_cpu_supports("popcnt");
	static std::uint32_t mask(int r) { return (std::uint32_t(1) << (r & 31)) - 1; }
	__attribute__((target("avx2,popcnt"), always_inline)) static __m256i counts(const Block &b, int r) {
		auto table = _mm256_setr_epi8(0, 1, 1, 2, 1, 2, 2, 3, 1, 2, 2, 3, 2, 3, 3, 4, 0, 1, 1, 2, 1, 2, 2, 3, 1, 2, 2, 3, 2, 3, 3, 4);
		auto x = _mm256_and_si256(_mm256_load_si256(reinterpret_cast<const __m256i *>(b.masks.data())), _mm256_set1_epi32(mask(r)));
		auto low = _mm256_shuffle_epi8(table, _mm256_and_si256(x, _mm256_set1_epi8(15)));
		auto high = _mm256_shuffle_epi8(table, _mm256_and_si256(_mm256_srli_epi16(x, 4), _mm256_set1_epi8(15)));
		auto pairs = _mm256_maddubs_epi16(_mm256_add_epi8(low, high), _mm256_set1_epi8(1));
		return _mm256_add_epi32(_mm256_madd_epi16(pairs, _mm256_set1_epi16(1)), _mm256_load_si256(reinterpret_cast<const __m256i *>(b.prefix.data())));
	}
	__attribute__((target("avx2,popcnt"))) T kth_avx2(int l, int r, int k) const {
		std::uint32_t x = 0;
		for (int d = 0; d < levels; ++d) {
			auto a = counts(bits[d][l >> 5], l), b = counts(bits[d][r >> 5], r);
			auto passed = _mm256_cmpgt_epi32(_mm256_set1_epi32(k + 1), _mm256_sub_epi32(b, a));
			int digit = std::popcount(unsigned(_mm256_movemask_ps(_mm256_castsi256_ps(passed))));
			x = (x << 3) | digit;
			if (d + 1 == levels) break;
			std::array<int, 9> ac{}, bc{};
			_mm256_storeu_si256(reinterpret_cast<__m256i *>(ac.data() + 1), a);
			_mm256_storeu_si256(reinterpret_cast<__m256i *>(bc.data() + 1), b);
			k -= bc[digit] - ac[digit];
			l = starts[d][digit] + ac[digit + 1] - ac[digit];
			r = starts[d][digit] + bc[digit + 1] - bc[digit];
		}
		return values[x];
	}
	T kth_scalar(int l, int r, int k) const {
		std::uint32_t x = 0;
		for (int d = 0; d < levels; ++d) {
			int lo = 0, hi = 8, al = 0, ar = 0, bl = l, br = r;
			const auto &a = bits[d][l >> 5], &b = bits[d][r >> 5];
			while (hi - lo > 1) {
				int m = (lo + hi) / 2;
				int p = a.prefix[m - 1] + std::popcount(a.masks[m - 1] & mask(l));
				int q = b.prefix[m - 1] + std::popcount(b.masks[m - 1] & mask(r));
				if (q - p <= k) lo = m, al = p, ar = q;
				else hi = m, bl = p, br = q;
			}
			x = (x << 3) | lo;
			k -= ar - al;
			l = starts[d][lo] + bl - al;
			r = starts[d][lo] + br - ar;
		}
		return values[x];
	}

  public:
	explicit WMOct(const std::vector<T> &a) : n(a.size()) {
		values = a;
		std::sort(values.begin(), values.end());
		values.erase(std::unique(values.begin(), values.end()), values.end());
		levels = (std::bit_width(unsigned(values.size() - 1)) + 2) / 3;
		std::vector<std::uint32_t> current(n), next(n);
		for (int i = 0; i < n; ++i) current[i] = std::lower_bound(values.begin(), values.end(), a[i]) - values.begin();
		bits.resize(levels, std::vector<Block>((n >> 5) + 1));
		starts.resize(levels);
		for (int d = 0; d < levels; ++d) {
			int shift = 3 * (levels - d - 1);
			std::array<std::uint32_t, 8> total{};
			for (int w = 0; w <= n >> 5; ++w) {
				auto &b = bits[d][w];
				b.prefix = total;
				for (int i = 0; i < std::min(32, n - 32 * w); ++i) {
					int digit = (current[32 * w + i] >> shift) & 7;
					for (int j = digit; j < 8; ++j) b.masks[j] |= std::uint32_t(1) << i;
				}
				for (int j = 0; j < 8; ++j) total[j] += std::popcount(b.masks[j]);
			}
			for (int j = 1; j < 8; ++j) starts[d][j] = total[j - 1];
			if (d + 1 < levels) {
				auto cursor = starts[d];
				for (auto x : current) next[cursor[(x >> shift) & 7]++] = x;
				current.swap(next);
			}
		}
	}
	T kth_smallest(int l, int r, int k) const {
		if (!levels) return values[0];
		return avx2 ? kth_avx2(l, r, k) : kth_scalar(l, r, k);
	}
};

sources.wm_rank_oct.cpp:
#include "wm_rank_probe/ternary/before.hpp"
#include "wm_rank_oct.hpp"
#include <chrono>
#include <cstdlib>
#include <iostream>
#include <random>

volatile std::uint64_t sink;
struct Query { int l, r, k; };
int main(int argc, char **argv) {
	int n = std::atoi(argv[1]), mode = std::atoi(argv[2]);
	std::mt19937_64 rng(814253);
	std::vector<std::int64_t> a(n);
	for (auto &x : a) x = mode == 1 ? rng() % 256 : mode == 2 ? std::int64_t(rng()) : rng() % 1000000000;
	std::vector<Query> query(20000);
	for (auto &z : query) {
		z.l = rng() % n; z.r = rng() % n;
		if (z.l > z.r) std::swap(z.l, z.r);
		++z.r; z.k = rng() % (z.r - z.l);
	}
	WaveletMatrixBaseline<std::int64_t> before(a);
	WMOct<std::int64_t> after(a);
	for (int pair = 0; pair < 7; ++pair) {
		double elapsed[2]{}; std::uint64_t sum[2]{};
		int repetitions = 0;
		do {
			for (int j = 0; j < 2; ++j) {
				int variant = (pair + repetitions + j) & 1;
				auto start = std::chrono::steady_clock::now();
				std::uint64_t total = 0;
				if (variant) for (auto z : query) total += std::uint64_t(after.kth_smallest(z.l, z.r, z.k));
				else for (auto z : query) total += std::uint64_t(before.kth_smallest(z.l, z.r, z.k));
				sum[variant] = total; sink = total;
				elapsed[variant] += std::chrono::duration<double>(std::chrono::steady_clock::now() - start).count();
			}
			if (sum[0] != sum[1]) return 1;
			++repetitions;
		} while (std::min(elapsed[0], elapsed[1]) < 0.12);
		std::cout << pair << ' ' << elapsed[0] / repetitions << ' ' << elapsed[1] / repetitions << ' ' << sum[0] << '\n';
	}
}

