		if constexpr (can_narrow) {
			Sum positive = 0, negative = 0;
			for (int i = 0; i < static_cast<int>(values.size()); ++i) {
				Sum v = Sum(values[i]) * (offsets[i + 1] - offsets[i]);
				if (v > 0) positive += v;
				else negative += v;
			}
			narrow_sums = positive <= std::numeric_limits<std::int64_t>::max() && negative >= std::numeric_limits<std::int64_t>::min();
		}
		if (narrow_sums) {
			compact_prefix.resize(ordered ? 1 : 3 * sum_levels + 1);
			prefix_sum(compact_prefix[0], original, 0, n);
		} else {
			sum_prefix.resize(ordered ? 1 : 3 * sum_levels + 1);
			prefix_sum(sum_prefix[0], original, 0, n);
		}
	}
	void construct(const std::vector<T> &a, bool with_sum) {
		assert(a.size() <= std::size_t(std::numeric_limits<int>::max()));
		sum_bits.clear();
		sum_middle.clear();
		sum_levels = 0;
		sum_prefix.clear();
		compact_prefix.clear();
		sum_ready = narrow_sums = false;
		n = static_cast<int>(a.size());
		dense = false;
		ordered = 0;
		if (!n || std::all_of(a.begin() + 1, a.end(), [&](const T &x) { return x == a.front(); })) {
			values.clear();
			if (n) values.push_back(a.front());
			values.shrink_to_fit();
			original.clear();
			positions.clear();
			offsets = {0, n};
			levels = 0;
			bits.clear();
			middle.clear();
			sum_ready = with_sum;
			return;
		}
		original = compress(a);
		if constexpr (std::is_integral_v<T> && sizeof(T) <= 8)
			dense = std::uint64_t(values.back()) - std::uint64_t(values.front()) == values.size() - 1;
		offsets.assign(values.size() + 1, 0);
		levels = (std::bit_width(unsigned(static_cast<int>(values.size()) - 1)) + 2) / 3;
		for (std::uint32_t x : original) ++offsets[x + 1];
		for (int i = 0; i < static_cast<int>(values.size()); ++i) offsets[i + 1] += offsets[i];
		if (ordered) {
			positions.clear();
			bits.clear();
			middle.clear();
			if constexpr (supports_sum)
				if (with_sum) init_sum();
			sum_ready = with_sum;
			return;
		}
		positions.resize(n);
		auto cursor = offsets;
		for (int i = 0; i < n; ++i) positions[cursor[original[i]]++] = i;
		auto current = original;
		bits.clear();
		bits.reserve(levels);
		middle.resize(levels);
		std::vector<std::uint32_t> next(n);
		for (int d = 0; d < levels; ++d) {
			bits.emplace_back(n);
			bits.back().build(current, 3 * (levels - 1 - d));
			auto totals = bits.back().ranks(n);
			middle[d][0] = 0;
			for (int i = 1; i < 8; ++i) middle[d][i] = middle[d][i - 1] + totals[i - 1];
			if (d + 1 < levels) partition(current, next, d);
		}
		if constexpr (supports_sum)
			if (with_sum) prepare_sum();
	}
	template <class S>
	S sum_smallest_impl_scalar(const std::vector<std::vector<S>> &prefix, int l, int r, int k) const
		requires supports_sum
	{
		S answer = 0;
		std::uint32_t x = 0;
		for (int d = 0; d < sum_levels; ++d) {
			auto step = sum_route(l, r, k, d);
			int base = 3 * d + 1;
			if (step.digit & 2) answer += prefix[base][step.high_r] - prefix[base][step.high_l];
			if (step.digit & 1) {
				const auto &row = prefix[base + 1 + (step.digit >> 1)];
				answer += row[step.zero_r] - row[step.zero_l];
			}
			k = step.k;
			if (!k) return answer;
			x = (x << 2) | step.digit;
			l = sum_middle[d][step.digit] + step.a;
			r = sum_middle[d][step.digit] + step.b;
		}
		return answer + S(values[x]) * k;
	}
#if defined(__x86_64__) || defined(__i386__)
	template <class S>
	__attribute__((target("avx2,popcnt")))S sum_smallest_impl_avx2(const std::vector<std::vector<S>> &prefix, int l, int r, int k) const
		requires supports_sum
	{
		S answer = 0;
		std::uint32_t x = 0;
		for (int d = 0; d < sum_levels; ++d) {
			auto step = sum_route(l, r, k, d);
			int base = 3 * d + 1;
			if (step.digit & 2) answer += prefix[base][step.high_r] - prefix[base][step.high_l];
			if (step.digit & 1) {
				const auto &row = prefix[base + 1 + (step.digit >> 1)];
				answer += row[step.zero_r] - row[step.zero_l];
			}
			k = step.k;
			if (!k) return answer;
			x = (x << 2) | step.digit;
			l = sum_middle[d][step.digit] + step.a;
			r = sum_middle[d][step.digit] + step.b;
		}
		return answer + S(values[x]) * k;
	}
#endif
	template <class S>
	S sum_smallest_impl(const std::vector<std::vector<S>> &prefix, int l, int r, int k) const
		requires supports_sum
	{
#if defined(__x86_64__) || defined(__i386__)
		if (vectorized) return sum_smallest_impl_avx2(prefix, l, r, k);
#endif
		return sum_smallest_impl_scalar(prefix, l, r, k);
	}

	T kth_scalar(int l, int r, int k) const {
		std::uint32_t x = 0;
		for (int d = 0; d < levels; ++d) {
			auto step = route_scalar(l, r, k, d);
			x = (x << 3) | step.digit;
			k = step.k;
			l = middle[d][step.digit] + step.a;
			r = middle[d][step.digit] + step.b;
		}
		return values[x];
	}
#if defined(__x86_64__) || defined(__i386__)
	__attribute__((target("avx2,popcnt"))) T kth_avx2(int l, int r, int k) const {
		std::uint32_t x = 0;
		for (int d = 0; d + 1 < levels; ++d) {
			auto step = route_avx2(l, r, k, d);
			x = (x << 3) | step.digit;
			k = step.k;
			l = middle[d][step.digit] + step.a;
			r = middle[d][step.digit] + step.b;
		}
		return values[(x << 3) | bits.back().select_avx2(l, r, k)];
	}
#endif

  public:
	using sum_type = Sum;
	WaveletMatrix() = default;
	explicit WaveletMatrix(const std::vector<T> &a) { build(a); }
	WaveletMatrix(const std::vector<T> &a, bool with_sum)
		requires supports_sum
	{ construct(a, with_sum); }
	void build(const std::vector<T> &a) { construct(a, false); }
	int size() const { return n; }
	bool empty() const { return n == 0; }
	T access(int i) const {
		assert(0 <= i && i < n);
		return values[levels ? original[i] : 0];
	}
	T operator[](int i) const { return access(i); }
	int count(int l, int r, const T &x) const {
		check(l, r);
		if (l == r) return 0;
		std::uint32_t c = code(x);
		if (c == values.size() || values[c] != x) return 0;
		if (!levels) return r - l;
		int start = offsets[c], end = offsets[c + 1];
		if (ordered) {
			int first = ordered > 0 ? start : n - end;
			return std::max(0, std::min(r, first + (end - start)) - std::max(l, first));
		}
		if (l == 0 && r == n) return end - start;
		if (end - start == 1) return int(l <= positions[start]) & int(positions[start] < r);
		if (end - start <= 16) {
			int answer = 0;
			for (int i = start; i < end; ++i) answer += unsigned(positions[i] - l) < unsigned(r - l);
			return answer;
		}
		if (r - l <= 8) {
			int answer = 0;
			for (int i = l; i < r; ++i) answer += original[i] == c;
			return answer;
		}
		auto [a, b] = interval(l, r, c);
		return b - a;
	}
	int rank(const T &x, int r) const { return count(0, r, x); }
	int select(const T &x, int k) const {
		std::uint32_t c = code(x);
		if (k < 0 || c == values.size() || values[c] != x || k >= offsets[c + 1] - offsets[c]) return -1;
		if (ordered) return (ordered > 0 ? offsets[c] : n - offsets[c + 1]) + k;
		return levels ? positions[offsets[c] + k] : k;
	}
	T kth_smallest(int l, int r, int k) const {
		check(l, r);
		assert(0 <= k && k < r - l);
		if (!levels) return values[0];
		if (ordered) return values[original[ordered > 0 ? l + k : r - 1 - k]];
		if (r - l <= 8) return values[small_codes(l, r)[k]];
#if defined(__x86_64__) || defined(__i386__)
		if (vectorized) return kth_avx2(l, r, k);
#endif
		return kth_scalar(l, r, k);
	}
	T kth_largest(int l, int r, int k) const {
		check(l, r);
		assert(0 <= k && k < r - l);
		return kth_smallest(l, r, r - l - 1 - k);
	}
	int range_freq(int l, int r, const T &upper) const {
		check(l, r);
		return less_than(l, r, code(upper));
	}
	int range_freq(int l, int r, const T &lower, const T &upper) const {
		check(l, r);
		if (!(lower < upper)) return 0;
		return less_than(l, r, code(upper)) - less_than(l, r, code(lower));
	}
	void prepare_sum() const
		requires supports_sum
	{
		if (sum_ready) return;
		if (!levels) {
			sum_ready = true;
			return;
		}
		init_sum();
		if (ordered) {
			sum_ready = true;
			return;
		}
		std::vector<std::uint32_t> current = original, next(n);
		sum_bits.reserve(sum_levels);
		sum_middle.resize(sum_levels);
		for (int d = 0; d < sum_levels; ++d) {
			sum_bits.emplace_back(n);
			sum_bits.back().build(current, 2 * (sum_levels - 1 - d));
			auto totals = sum_bits.back().ranks(n);
			sum_middle[d] = {0, totals[0], totals[0] + totals[1], totals[0] + totals[1] + totals[2]};
			if (narrow_sums) partition_sum(compact_prefix, current, next, d);
			else partition_sum(sum_prefix, current, next, d);
		}
		sum_ready = true;
	}
	Sum range_sum(int l, int r) const
		requires supports_sum
	{
		check(l, r);
		if (l == r) return Sum(0);
		if (!levels) return Sum(values[0]) * (r - l);
		if (!sum_ready && r - l <= 8) {
			Sum answer = 0;
			for (int i = l; i < r; ++i) answer += Sum(values[original[i]]);
			return answer;
		}
		prepare_sum();
		if (narrow_sums) return compact_prefix[0][r] - compact_prefix[0][l];
		return sum_prefix[0][r] - sum_prefix[0][l];
	}
	Sum sum_smallest(int l, int r, int k) const
		requires supports_sum
	{
		check(l, r);
		assert(0 <= k && k <= r - l);
		if (!k) return Sum(0);
		if (k == r - l) return range_sum(l, r);
		if (!levels) return Sum(values[0]) * k;
		if (ordered) return ordered > 0 ? range_sum(l, l + k) : range_sum(r - k, r);
		if (k == 1) return Sum(kth_smallest(l, r, 0));
		if (r - l <= 8) {
			auto a = small_codes(l, r);
			Sum answer = 0;
			for (int i = 0; i < k; ++i) answer += Sum(values[a[i]]);
			return answer;
		}
		prepare_sum();
		if (narrow_sums) return sum_smallest_impl(compact_prefix, l, r, k);
		return sum_smallest_impl(sum_prefix, l, r, k);
	}
	Sum sum_largest(int l, int r, int k) const
		requires supports_sum
	{
		check(l, r);
		assert(0 <= k && k <= r - l);
		if (!k) return Sum(0);
		if (!levels) return Sum(values[0]) * k;
		if (ordered) return ordered > 0 ? range_sum(r - k, r) : range_sum(l, l + k);
		if (k == 1) return Sum(kth_largest(l, r, 0));
		if (k == r - l) return range_sum(l, r);
		if (r - l <= 8) {
			auto a = small_codes(l, r);
			Sum answer = 0;
			for (int i = r - l - k; i < r - l; ++i) answer += Sum(values[a[i]]);
			return answer;
		}
		return range_sum(l, r) - sum_smallest(l, r, r - l - k);
	}
	std::optional<T> prev_value(int l, int r, const T &upper) const {
		check(l, r);
		if (!levels) return l < r && values[0] < upper ? std::optional<T>(values[0]) : std::nullopt;
		if (!ordered) {
			auto x = code(upper);
			if (!x) return std::nullopt;
			return neighbor<true>(l, r, x - 1);
		}
		int k = range_freq(l, r, upper);
		if (!k) return std::nullopt;
		return kth_smallest(l, r, k - 1);
	}
	std::optional<T> next_value(int l, int r, const T &lower) const {
		check(l, r);
		if (!levels) return l < r && !(values[0] < lower) ? std::optional<T>(values[0]) : std::nullopt;
		if (!ordered) {
			auto x = code(lower);
			if (x == values.size()) return std::nullopt;
			return neighbor<false>(l, r, x);
		}
		int k = range_freq(l, r, lower);
		if (k == r - l) return std::nullopt;
		return kth_smallest(l, r, k);
	}
};

template <class T>
WaveletMatrix(const std::vector<T> &, bool) -> WaveletMatrix<T>;

#endif

radix8_quad_sum_prototype.component:
#ifndef OCT_BIT_VECTOR_HPP
#define OCT_BIT_VECTOR_HPP

#include <algorithm>
#include <array>
#include <bit>
#include <cassert>
#include <cstddef>
#include <cstdint>
#include <vector>
#if defined(__x86_64__) || defined(__i386__)
#include <immintrin.h>
#endif

struct OctBitVector {
	struct alignas(64) Block {
		std::array<std::uint32_t, 8> masks{}, prefix{};
	};
	struct Route {
		int digit, a, b, k, half_l, half_r, quarter_l, quarter_r, zero_l, zero_r;
	};
	int n;
	std::vector<Block> blocks;
	static std::uint32_t mask(int r) { return (std::uint32_t(1) << (r & 31)) - 1; }
	static bool has_avx2() {
#if defined(__x86_64__) || defined(__i386__)
		return __builtin_cpu_supports("avx2") && __builtin_cpu_supports("popcnt");
#else
		return false;
#endif
	}
	static std::array<std::uint32_t, 8> cumulative(std::uint32_t low, std::uint32_t mid, std::uint32_t high, std::uint32_t valid) {
		return {~(high | mid | low) & valid, ~(high | mid) & valid, ~high & ~(mid & low) & valid,
				~high & valid, (~high | ~(mid | low)) & valid, ~(high & mid) & valid, ~(high & mid & low) & valid, valid};
	}
	explicit OctBitVector(int n = 0) : n(n), blocks((n >> 5) + 1) {}
	void build_scalar(const std::vector<std::uint32_t> &a, int shift) {
		std::array<std::uint32_t, 8> total{};
		for (int w = 0; w < static_cast<int>(blocks.size()); ++w) {
			std::uint32_t low = 0, mid = 0, high = 0;
			int start = 32 * w, length = std::min(32, n - start);
			for (int j = 0; j < length; ++j) {
				auto x = a[start + j] >> shift;
				low |= (x & 1) << j;
				mid |= ((x >> 1) & 1) << j;
				high |= ((x >> 2) & 1) << j;
			}
			auto &b = blocks[w];
			b.masks = cumulative(low, mid, high, length == 32 ? ~std::uint32_t(0) : mask(length));
			b.prefix = total;
			for (int i = 0; i < 8; ++i) total[i] += std::popcount(b.masks[i]);
		}
	}
#if defined(__x86_64__) || defined(__i386__)
	__attribute__((target("avx2,popcnt"), always_inline)) static __m256i popcounts(__m256i x) {
		const auto table = _mm256_setr_epi8(0, 1, 1, 2, 1, 2, 2, 3, 1, 2, 2, 3, 2, 3, 3, 4, 0, 1, 1, 2, 1, 2, 2, 3, 1, 2, 2, 3, 2, 3, 3, 4);
		const auto nibble = _mm256_set1_epi8(15);
		auto low = _mm256_shuffle_epi8(table, _mm256_and_si256(x, nibble));
		auto high = _mm256_shuffle_epi8(table, _mm256_and_si256(_mm256_srli_epi16(x, 4), nibble));
		auto pairs = _mm256_maddubs_epi16(_mm256_add_epi8(low, high), _mm256_set1_epi8(1));
		return _mm256_madd_epi16(pairs, _mm256_set1_epi16(1));
	}
	__attribute__((target("avx2,popcnt"), always_inline)) static __m256i prefix_counts(const Block &b, int r) {
		auto masked = _mm256_and_si256(_mm256_load_si256(reinterpret_cast<const __m256i *>(b.masks.data())), _mm256_set1_epi32(mask(r)));
		return _mm256_add_epi32(popcounts(masked), _mm256_load_si256(reinterpret_cast<const __m256i *>(b.prefix.data())));
	}
	__attribute__((target("avx2,popcnt"))) void build_avx2(const std::vector<std::uint32_t> &a, int shift) {
		std::array<std::uint32_t, 8> total{};
		auto low_shift = _mm_cvtsi32_si128(31 - shift), mid_shift = _mm_cvtsi32_si128(30 - shift), high_shift = _mm_cvtsi32_si128(29 - shift);
		for (int w = 0; w < static_cast<int>(blocks.size()); ++w) {
			std::uint32_t low = 0, mid = 0, high = 0;
			int start = 32 * w, length = std::min(32, n - start), j = 0;
			for (; j + 8 <= length; j += 8) {
				auto x = _mm256_loadu_si256(reinterpret_cast<const __m256i *>(a.data() + start + j));
				low |= std::uint32_t(_mm256_movemask_ps(_mm256_castsi256_ps(_mm256_sll_epi32(x, low_shift)))) << j;
				mid |= std::uint32_t(_mm256_movemask_ps(_mm256_castsi256_ps(_mm256_sll_epi32(x, mid_shift)))) << j;
				high |= std::uint32_t(_mm256_movemask_ps(_mm256_castsi256_ps(_mm256_sll_epi32(x, high_shift)))) << j;
			}
			for (; j < length; ++j) {
				auto x = a[start + j] >> shift;
				low |= (x & 1) << j;
				mid |= ((x >> 1) & 1) << j;
				high |= ((x >> 2) & 1) << j;
			}
			auto &b = blocks[w];
			b.masks = cumulative(low, mid, high, length == 32 ? ~std::uint32_t(0) : mask(length));
			b.prefix = total;
			auto counts = popcounts(_mm256_load_si256(reinterpret_cast<const __m256i *>(b.masks.data())));
			auto updated = _mm256_add_epi32(counts, _mm256_loadu_si256(reinterpret_cast<const __m256i *>(total.data())));
			_mm256_storeu_si256(reinterpret_cast<__m256i *>(total.data()), updated);
		}
	}
	template <bool ForSum = false>
	__attribute__((target("avx2,popcnt"), always_inline)) Route route_avx2(int l, int r, int k) const {
		auto left = prefix_counts(blocks[l >> 5], l), right = prefix_counts(blocks[r >> 5], r);
		auto passed = _mm256_cmpgt_epi32(_mm256_set1_epi32(k + 1), _mm256_sub_epi32(right, left));
		int digit = std::popcount(unsigned(_mm256_movemask_ps(_mm256_castsi256_ps(passed))));
		if constexpr (ForSum) {
			int quarter = digit & 4, zero = digit & 6;
			auto index = _mm256_setr_epi32(digit - 1, digit, 3, quarter - 1, quarter + 1, zero - 1, zero, 0);
			auto valid = _mm256_setr_epi32(digit ? -1 : 0, -1, -1, quarter ? -1 : 0, -1, zero ? -1 : 0, -1, 0);
			left = _mm256_and_si256(_mm256_permutevar8x32_epi32(left, index), valid);
			right = _mm256_and_si256(_mm256_permutevar8x32_epi32(right, index), valid);
			auto al = _mm256_castsi256_si128(left), ah = _mm256_extracti128_si256(left, 1);
			auto bl = _mm256_castsi256_si128(right), bh = _mm256_extracti128_si256(right, 1);
			int a = _mm_cvtsi128_si32(al), b = _mm_cvtsi128_si32(bl);
			return {digit, _mm_extract_epi32(al, 1) - a, _mm_extract_epi32(bl, 1) - b, k - b + a,
					_mm_extract_epi32(al, 2), _mm_extract_epi32(bl, 2), _mm_cvtsi128_si32(ah) - _mm_extract_epi32(al, 3), _mm_cvtsi128_si32(bh) - _mm_extract_epi32(bl, 3),
					_mm_extract_epi32(ah, 2) - _mm_extract_epi32(ah, 1), _mm_extract_epi32(bh, 2) - _mm_extract_epi32(bh, 1)};
		}
		std::array<int, 9> a{}, b{};
		_mm256_storeu_si256(reinterpret_cast<__m256i *>(a.data() + 1), left);
		_mm256_storeu_si256(reinterpret_cast<__m256i *>(b.data() + 1), right);
		if constexpr (ForSum) {
			int quarter = digit & 4, zero = digit & 6;
			return {digit, a[digit + 1] - a[digit], b[digit + 1] - b[digit], k - b[digit] + a[digit], a[4], b[4], a[quarter + 2] - a[quarter], b[quarter + 2] - b[quarter], a[zero + 1] - a[zero], b[zero + 1] - b[zero]};
		} else return {digit, a[digit + 1] - a[digit], b[digit + 1] - b[digit], k - b[digit] + a[digit], 0, 0, 0, 0, 0, 0};
	}
	__attribute__((target("avx2,popcnt"), always_inline)) int select_avx2(int l, int r, int k) const {
		__m256i counts;
		if ((l >> 5) == (r >> 5)) {
			auto m = _mm256_set1_epi32(mask(l) ^ mask(r));
			counts = popcounts(_mm256_and_si256(_mm256_load_si256(reinterpret_cast<const __m256i *>(blocks[l >> 5].masks.data())), m));
		} else counts = _mm256_sub_epi32(prefix_counts(blocks[r >> 5], r), prefix_counts(blocks[l >> 5], l));
		auto passed = _mm256_cmpgt_epi32(_mm256_set1_epi32(k + 1), counts);
		return std::popcount(unsigned(_mm256_movemask_ps(_mm256_castsi256_ps(passed))));
	}
#endif
	void build(const std::vector<std::uint32_t> &a, int shift) {
		assert(a.size() == std::size_t(n) && 0 <= shift && shift <= 30);
#if defined(__x86_64__) || defined(__i386__)
		if (has_avx2()) { build_avx2(a, shift); return; }
#endif
		build_scalar(a, shift);
	}
	int below(int r, int digit) const {
		if (!digit) return 0;
		const auto &b = blocks[r >> 5];
		return b.prefix[digit - 1] + std::popcount(b.masks[digit - 1] & mask(r));
	}
	int rank(int r, int digit) const {
		const auto &b = blocks[r >> 5];
		return b.prefix[digit] - (digit ? b.prefix[digit - 1] : 0) + std::popcount((b.masks[digit] ^ (digit ? b.masks[digit - 1] : 0)) & mask(r));
	}
	std::array<int, 8> ranks(int r) const {
		std::array<int, 8> counts;
		int previous = 0;
		for (int i = 0; i < 8; ++i) {
			int current = below(r, i + 1);
			counts[i] = current - previous;
			previous = current;
		}
		return counts;
	}
	[[gnu::always_inline]] Route route_sum(int l, int r, int k) const {
		int half_l = below(l, 4), half_r = below(r, 4);
		bool high = k >= half_r - half_l;
		k -= high ? half_r - half_l : 0;
		int base_l = high ? half_l : 0, base_r = high ? half_r : 0;
		int total_l = high ? l - half_l : half_l, total_r = high ? r - half_r : half_r;
		int quarter_l = below(l, 4 * high + 2) - base_l, quarter_r = below(r, 4 * high + 2) - base_r;
		bool mid = k >= quarter_r - quarter_l;
		k -= mid ? quarter_r - quarter_l : 0;
		base_l += mid ? quarter_l : 0;
		base_r += mid ? quarter_r : 0;
		total_l = mid ? total_l - quarter_l : quarter_l;
		total_r = mid ? total_r - quarter_r : quarter_r;
		int digit = 4 * high + 2 * mid;
		int zero_l = below(l, digit + 1) - base_l, zero_r = below(r, digit + 1) - base_r;
		bool low = k >= zero_r - zero_l;
		k -= low ? zero_r - zero_l : 0;
		return {digit + low, low ? total_l - zero_l : zero_l, low ? total_r - zero_r : zero_r, k, half_l, half_r, quarter_l, quarter_r, zero_l, zero_r};
	}
	template <bool ForSum = false>
	Route route_scalar(int l, int r, int k) const {
		if constexpr (ForSum) return route_sum(l, r, k);
		std::array<int, 9> a{}, b{};
		for (int i = 1; i <= 8; ++i) a[i] = below(l, i), b[i] = below(r, i);
		int digit = 0;
		while (k >= b[digit + 1] - a[digit + 1]) ++digit;
		if constexpr (ForSum) {
			int quarter = digit & 4, zero = digit & 6;
			return {digit, a[digit + 1] - a[digit], b[digit + 1] - b[digit], k - b[digit] + a[digit], a[4], b[4], a[quarter + 2] - a[quarter], b[quarter + 2] - b[quarter], a[zero + 1] - a[zero], b[zero + 1] - b[zero]};
		} else return {digit, a[digit + 1] - a[digit], b[digit + 1] - b[digit], k - b[digit] + a[digit], 0, 0, 0, 0, 0, 0};
	}
};

#endif

scripts.wm_rank_probe.py:
import fcntl
import hashlib
import json
import os
import pathlib
import statistics
import subprocess
import time

root = pathlib.Path(__file__).resolve().parents[2]
cache = root / '.verify-helper/cache/wm_rank_probe'
cache.mkdir(exist_ok=True)
base = '523956f'
wm = subprocess.check_output(['git', 'show', f'{base}:data_structure/wavelet_matrix.hpp'], cwd=root).decode()
quad = subprocess.check_output(['git', 'show', f'{base}:components/quad_bit_vector.hpp'], cwd=root).decode()
bench = (root / 'test/benchmark/wavelet_matrix_neighbors.cpp').read_text()
bench = bench[bench.index('#include <chrono>'):]
old = '''\t\t\tstd::array<int, 5> a{0, la, lb, lc, l}, b{0, ra, rb, rc, r};
\t\t\tint base = digit & 2;
\t\t\treturn {digit, a[digit + 1] - a[digit], b[digit + 1] - b[digit], k - b[digit] + a[digit], lb, rb, a[base + 1] - a[base], b[base + 1] - b[base]};'''
ternary = '''\t\t\tint a = digit < 2 ? (digit ? la : 0) : (digit == 2 ? lb : lc);
\t\t\tint b = digit < 2 ? (digit ? ra : 0) : (digit == 2 ? rb : rc);
\t\t\tint ea = digit < 2 ? (digit ? lb : la) : (digit == 2 ? lc : l);
\t\t\tint eb = digit < 2 ? (digit ? rb : ra) : (digit == 2 ? rc : r);
\t\t\treturn {digit, ea - a, eb - b, k - b + a, lb, rb, 0, 0};'''
binary = '''\t\t\tbool high = k >= rb - lb;
\t\t\tint a = high ? lc : la, b = high ? rc : ra;
\t\t\tint z = high ? lb : 0, t = high ? rb : 0;
\t\t\tbool low = k >= b - a;
\t\t\treturn {digit, (low ? (high ? l : lb) : a) - (low ? a : z), (low ? (high ? r : rb) : b) - (low ? b : t), k - (low ? b - a : t - z), lb, rb, 0, 0};'''
# binary candidate computes selected counts directly from cumulative ranks.
binary = '''\t\t\tbool high = k >= rb - lb;
\t\t\tint a0 = high ? lb : 0, b0 = high ? rb : 0;
\t\t\tint a1 = high ? lc : la, b1 = high ? rc : ra;
\t\t\tint a2 = high ? l : lb, b2 = high ? r : rb;
\t\t\tbool low = digit & 1;
\t\t\tint a = low ? a1 : a0, b = low ? b1 : b0;
\t\t\treturn {digit, (low ? a2 : a1) - a, (low ? b2 : b1) - b, k - b + a, lb, rb, 0, 0};'''
hierarchy = wm.replace('if constexpr (ForSum) {', 'if constexpr (true) {')
variants = {'ternary': (wm.replace(old, ternary), quad), 'binary_select': (wm.replace(old, binary), quad), 'hierarchy': (hierarchy, quad)}
cumulative = quad.replace('blocks[w] = {low, high, counts};', 'blocks[w] = {low, high, {counts[0], counts[0] + counts[1], counts[0] + counts[1] + counts[2], counts[3]}};')
cumulative = cumulative.replace('return b.prefix[digit] + std::popcount', 'return (digit == 0 ? b.prefix[0] : digit == 1 ? b.prefix[1] - b.prefix[0] : digit == 2 ? (r & ~63) - b.prefix[1] - b.prefix[3] : b.prefix[3]) + std::popcount')
cumulative = cumulative.replace('b.prefix[0] + b.prefix[1] + std::popcount(~b.high', 'b.prefix[1] + std::popcount(~b.high')
cumulative = cumulative.replace('a[1] = b.prefix[1]', 'a[1] = b.prefix[1] - b.prefix[0]')
cumulative = cumulative.replace('a[2] = b.prefix[2]', 'a[2] = (r & ~63) - b.prefix[1] - b.prefix[3]')
cw = wm.replace('left.prefix[2] + left.prefix[3]', '(l & ~63) - left.prefix[1]').replace('right.prefix[2] + right.prefix[3]', '(r & ~63) - right.prefix[1]')
cw = cw.replace('left.prefix[2 * high]', '(high ? (l & ~63) - left.prefix[1] - left.prefix[3] : left.prefix[0])').replace('right.prefix[2 * high]', '(high ? (r & ~63) - right.prefix[1] - right.prefix[3] : right.prefix[0])')
cw = cw.replace('left.prefix[0] + left.prefix[1]', 'left.prefix[1]').replace('right.prefix[0] + right.prefix[1]', 'right.prefix[1]')
variants['cumulative'] = (cw, cumulative)
variants['cumulative_ternary'] = (cw.replace(old, ternary), cumulative)
variants['cumulative_binary'] = (cw.replace(old, binary), cumulative)

old_kth = '''\t\tstd::uint32_t x = 0;
\t\tfor (int d = 0; d < levels; ++d) {
\t\t\tauto step = route(l, r, k, d);
\t\t\tx = (x << 2) | step.digit;
\t\t\tk = step.k;
\t\t\tl = middle[d][step.digit] + step.a;
\t\t\tr = middle[d][step.digit] + step.b;
\t\t}
\t\treturn values[x];'''
last_kth = old_kth.replace('d < levels;', 'd + 1 < levels;').replace('\t\treturn values[x];', '\t\treturn values[(x << 2) | route(l, r, k, levels - 1).digit];')
assert old_kth in wm
variants['last'] = (wm.replace(old_kth, last_kth), quad)
last_word = '''\t\tint digit;
\t\tif ((l >> 6) == (r >> 6)) {
\t\t\tconst auto &b = bits.back().blocks[l >> 6];
\t\t\tstd::uint64_t m = ((std::uint64_t(1) << (l & 63)) - 1) ^ ((std::uint64_t(1) << (r & 63)) - 1);
\t\t\tdigit = (k >= std::popcount(~(b.low | b.high) & m)) + (k >= std::popcount(~b.high & m)) + (k >= r - l - std::popcount((b.low & b.high) & m));
\t\t} else digit = route(l, r, k, levels - 1).digit;
\t\treturn values[(x << 2) | digit];'''
variants['last_word'] = (wm.replace(old_kth, last_kth.replace('\t\treturn values[(x << 2) | route(l, r, k, levels - 1).digit];', last_word)), quad)

results = {'baseline': base, 'compiler': subprocess.check_output(['g++', '--version'], text=True).splitlines()[0], 'flags': ['-std=c++23', '-O2', '-march=native'], 'cases': []}
lock = open('/tmp/cp-wm-opt.lock', 'w')
for name, (candidate_wm, candidate_quad) in variants.items():
    if os.environ.get('WM_CANDIDATES') and name not in os.environ['WM_CANDIDATES'].split(','):
        continue
    directory = cache / name
    directory.mkdir(exist_ok=True)
    for prefix, h, q in [('before', wm, quad), ('after', candidate_wm, candidate_quad)]:
        h = h.replace('WAVELET_MATRIX_HPP', f'WAVELET_MATRIX_{prefix.upper()}_HPP').replace('WaveletMatrix', 'WaveletMatrixBaseline' if prefix == 'before' else 'WaveletMatrix')
        q = q.replace('QUAD_BIT_VECTOR_HPP', f'QUAD_BIT_VECTOR_{prefix.upper()}_HPP').replace('QuadBitVector', f'QuadBitVector_{prefix}')
        h = h.replace('QuadBitVector', f'QuadBitVector_{prefix}').replace('../components/quad_bit_vector.hpp', f'{prefix}_quad.hpp')
        (directory / f'{prefix}_quad.hpp').write_text(q)
        (directory / f'{prefix}.hpp').write_text(h)
    source = '#include "before.hpp"\n#include "after.hpp"\n' + bench
    (directory / 'bench.cpp').write_text(source)
    binary_file = directory / 'bench'
    fcntl.flock(lock, fcntl.LOCK_EX)
    try:
        subprocess.run(['g++', *results['flags'], '-I', str(root), str(directory / 'bench.cpp'), '-o', str(binary_file)], check=True)
    finally:
        fcntl.flock(lock, fcntl.LOCK_UN)
    for n, mode, op in [(200000, m, o) for m in (0, 1, 2) for o in (1, 2, 4, 7)]:
        fcntl.flock(lock, fcntl.LOCK_EX)
        try:
            raw = subprocess.check_output(['taskset', '-c', '2', str(binary_file), str(n), str(mode), str(op), '0', '0.035', '3', 'uniform'], text=True)
        finally:
            fcntl.flock(lock, fcntl.LOCK_UN)
        pairs = {}
        for line in raw.splitlines():
            pair, variant, cpu, wall, checksum, reps = line.split()
            pairs.setdefault(pair, {})[variant] = {'cpu': float(cpu), 'wall': float(wall), 'checksum': checksum, 'repetitions': int(reps)}
        ratio = statistics.median(p['0']['cpu'] / p['1']['cpu'] for p in pairs.values())
        item = {'candidate': name, 'n': n, 'mode': mode, 'operation': op, 'ratio': ratio, 'pairs': pairs}
        results['cases'].append(item)
        print(json.dumps(item), flush=True)
        (cache / os.environ.get('WM_OUTPUT', 'results.json')).write_text(json.dumps(results, indent=2) + '\n')

scripts.wm_rank_generate.py:
import pathlib
import subprocess

root = pathlib.Path(__file__).resolve().parents[2]
source = subprocess.check_output(['git', 'show', '523956f:data_structure/wavelet_matrix.hpp'], cwd=root, text=True)
source = source.replace('"../components/quad_bit_vector.hpp"', '"components/oct_bit_vector.hpp"').replace('QuadBitVector', 'OctBitVector')
source = source.replace('std::vector<std::array<int, 4>> middle;', 'std::vector<std::array<int, 8>> middle;\n\tbool vectorized = BitVector::has_avx2();')
source = source.replace('2 * (levels', '3 * (levels').replace(' & 3', ' & 7').replace('<< 2', '<< 3').replace('std::uint32_t(3)', 'std::uint32_t(7)')
source = source.replace('std::array<std::pair<int, int>, 16>', 'std::array<std::pair<int, int>, 11>').replace('digit < 4', 'digit < 8')
source = source.replace('digit == 3', 'digit == 7')
source = source.replace('(std::bit_width(unsigned(static_cast<int>(values.size()) - 1)) + 1) / 2', '(std::bit_width(unsigned(static_cast<int>(values.size()) - 1)) + 2) / 3')
source = source.replace('3 * levels + 1', '7 * levels + 1')
source = source.replace('middle[d] = {0, totals[0], totals[0] + totals[1], totals[0] + totals[1] + totals[2]};', 'middle[d][0] = 0;\n\t\t\tfor (int i = 1; i < 8; ++i) middle[d][i] = middle[d][i - 1] + totals[i - 1];')

def section(text, name):
    start = text.index(name)
    brace = text.index('{', start)
    depth = 1
    end = brace + 1
    while depth:
        depth += (text[end] == '{') - (text[end] == '}')
        end += 1
    return text[start:end]

old = section(source, '\tvoid partition_sum(')
new = '''\tvoid partition_sum(std::vector<std::vector<S>> &prefix, std::vector<std::uint32_t> &current, std::vector<std::uint32_t> &next, int d) const
\t\trequires supports_sum
\t{
\t\tint shift = 3 * (levels - 1 - d), base = 7 * d + 1;
\t\tstd::array<int, 2> halves{0, middle[d][4]};
\t\tfor (std::uint32_t x : current) next[halves[(x >> (shift + 2)) & 1]++] = x;
\t\tprefix_sum(prefix[base], next, 0, middle[d][4]);
\t\tcurrent.swap(next);
\t\tstd::array<int, 4> quarters{0, middle[d][2], middle[d][4], middle[d][6]};
\t\tfor (std::uint32_t x : current) next[quarters[(x >> (shift + 1)) & 3]++] = x;
\t\tprefix_sum(prefix[base + 1], next, 0, middle[d][2]);
\t\tprefix_sum(prefix[base + 2], next, middle[d][4], middle[d][6]);
\t\tcurrent.swap(next);
\t\tpartition(current, next, d);
\t\tfor (int i = 0; i < 4; ++i) prefix_sum(prefix[base + 3 + i], current, middle[d][2 * i], middle[d][2 * i + 1]);
\t}'''
source = source.replace(old, new)
start = source.index('\tstruct Route {')
endsection = section(source[start:], '\t[[gnu::always_inline]] Route route(')
end = start + source[start:].index(endsection) + len(endsection)
source = source[:start] + '''\tusing Route = typename BitVector::Route;
\ttemplate <bool ForSum = false>
\t[[gnu::always_inline]] Route route_scalar(int l, int r, int k, int d) const {
\t\treturn bits[d].template route_scalar<ForSum>(l, r, k);
\t}
#if defined(__x86_64__) || defined(__i386__)
\ttemplate <bool ForSum = false>
\t__attribute__((target("avx2,popcnt"), always_inline)) Route route_avx2(int l, int r, int k, int d) const {
\t\treturn bits[d].template route_avx2<ForSum>(l, r, k);
\t}
#endif''' + source[end:]
old = section(source, '\tS sum_smallest_impl(')
new = old.replace('int base = 3 * d + 1;', 'int base = 7 * d + 1;')
new = new.replace('if (step.digit & 2) answer += prefix[base][step.high_r] - prefix[base][step.high_l];', 'if (step.digit & 4) answer += prefix[base][step.half_r] - prefix[base][step.half_l];\n\t\t\tif (step.digit & 2) {\n\t\t\t\tconst auto &row = prefix[base + 1 + (step.digit >> 2)];\n\t\t\t\tanswer += row[step.quarter_r] - row[step.quarter_l];\n\t\t\t}')
new = new.replace('prefix[base + 1 + (step.digit >> 1)]', 'prefix[base + 3 + (step.digit >> 1)]')
source = source.replace(old, new)

methods = [
    ('\tstd::pair<int, int> interval(', 'interval', 'std::pair<int, int>', 'int l, int r, std::uint32_t x', 'l, r, x', ''),
    ('\tint less_than(', 'less_than', 'int', 'int l, int r, std::uint32_t x', 'l, r, x', ''),
    ('\tstd::optional<T> neighbor(', 'neighbor', 'std::optional<T>', 'int l, int r, std::uint32_t x', 'l, r, x', '\ttemplate <bool Previous>\n'),
    ('\tS sum_smallest_impl(', 'sum_smallest_impl', 'S', 'const std::vector<std::vector<S>> &prefix, int l, int r, int k', 'prefix, l, r, k', '\ttemplate <class S>\n'),
]
for signature, name, result, parameters, arguments, template in methods:
    old = section(source, signature)
    suffix = '<Previous>' if name == 'neighbor' else ''
    require = '\n\t\trequires supports_sum' if name == 'sum_smallest_impl' else ''
    scalar = old.replace(name + '(', name + '_scalar(', 1).replace('route(', 'route_scalar(').replace('route<true>', 'route_scalar<true>')
    avx2 = old.replace(name + '(', name + '_avx2(', 1).replace('route(', 'route_avx2(').replace('route<true>', 'route_avx2<true>')
    avx2 = '\t__attribute__((target("avx2,popcnt")))' + avx2[1:]
    wrapper = f'\t{result} {name}({parameters}) const{require} {{\n#if defined(__x86_64__) || defined(__i386__)\n\t\tif (vectorized) return {name}_avx2{suffix}({arguments});\n#endif\n\t\treturn {name}_scalar{suffix}({arguments});\n\t}}'
    source = source.replace(template + old, template + scalar + '\n#if defined(__x86_64__) || defined(__i386__)\n' + template + avx2 + '\n#endif\n' + template + wrapper)

old = section(source, '\tT kth_smallest(')
prefix = old[:old.index('\t\tstd::uint32_t x = 0;')]
loop = old[old.index('\t\tstd::uint32_t x = 0;'):]
scalar = '\tT kth_scalar(int l, int r, int k) const {\n' + loop.replace('route(', 'route_scalar(')
avx2loop = loop.replace('d < levels;', 'd + 1 < levels;').replace('route(', 'route_avx2(').replace('return values[x];', 'return values[(x << 3) | bits.back().select_avx2(l, r, k)];')
avx2 = '\t__attribute__((target("avx2,popcnt"))) T kth_avx2(int l, int r, int k) const {\n' + avx2loop
source = source.replace('\n  public:', '\n' + scalar + '\n#if defined(__x86_64__) || defined(__i386__)\n' + avx2 + '\n#endif\n\n  public:', 1)
wrapper = prefix + '''#if defined(__x86_64__) || defined(__i386__)
\t\tif (vectorized) return kth_avx2(l, r, k);
#endif
\t\treturn kth_scalar(l, r, k);
\t}'''
source = source.replace(old, wrapper)
assert 'route(' not in source
(root / '.verify-helper/cache/wm_rank_candidate.hpp').write_text(source)
unit = (root / 'test/unit/wavelet_matrix.cpp').read_text().replace('data_structure/wavelet_matrix.hpp', '.verify-helper/cache/wm_rank_candidate.hpp')
(root / '.verify-helper/cache/wm_rank_unit.cpp').write_text(unit)
